#[path = "/Users/chazu/dev/zig/birnam/rust/birnam-siphon/tests/support/mod.rs"] mod support;
use support::*;
use birnam_abi::{Oop,borrowed_bytes,id_protocol::Operand};
use std::{os::unix::ffi::OsStrExt,collections::BTreeMap};
unsafe extern "C" {fn clock_gettime_nsec_np(clock:i32)->u64;}
fn main(){unsafe{
 let metrics=std::env::args().any(|s|s=="--metrics");
 let id=id();let ns=load(id,"bootstrap",&[Operand::bytes(directory().as_os_str().as_bytes())]);
 let named=|name:&[u8]|object(send(id,ns,b"resolveGlobal:",&[Operand::object(id.intern_name(name).unwrap())]));
 let roots=named(b"Roots");let gc=named(b"GC");let keep=|o:Oop|{retain(id,roots,o);o};
 let text=|b:&[u8]|keep(object(send(id,named(b"String"),b"fromBytes:",&[Operand::bytes(b)])));
 for module in ["stdlib","stacklessControl"] {
  let path=directory().join(format!("libbirnam_{module}.dylib"));
  let answer=object(send(id,named(b"Codegen"),b"load:",&[Operand::object(text(path.as_os_str().as_bytes()))]));
  assert_eq!(object(send(id,answer,b"isError",&[])),named(b"false"));
  send(id,named(b"Module"),b"markLoaded:",&[Operand::object(id.intern_name(module.as_bytes()).unwrap())]);
 }
 let eval=|s:&str|{let o=keep(object(send(id,named(b"Codegen"),b"eval:",&[Operand::object(text(s.as_bytes()))])));assert_eq!(object(send(id,o,b"isError",&[])),named(b"false"),"{s}");o};
 let cases=[
 ("empty-block","[| nil]","nil",200),
 ("captured-value","let a := 12345; [| a]","12345",200),
 ("integer-add","let a := 12345; let b := 37; [| [a + b]]","12382",200),
 ("integer-compare","let a := 12345; let b := 37; [| [a > b]]","true",200),
 ("coordinate-index","let x := 14; let y := 12; let width := 60; [| [[y * width] + x]]","734",200),
 ("symbol-identity","let a := #wall; let b := #wall; [| [a == b]]","true",200),
 ("symbol-print","let a := #wall; [| [a printString]]","#wall",200),
 ("symbol-print-equality","let a := #wall; let b := #wall; [| [[a printString] = [b printString]]]","true",200),
 ("map-hit","let map := {734 -> #floor}; let key := 734; [| [map at: key]]","#floor",200),
 ("map-miss-block","let map := {734 -> #floor}; let key := 735; [| [map at: key ifAbsent: [| #wall]]]","#wall",200),
 ("conditional-inline","let a := 12345; let flag := true; [| [flag ifTrue: [| a] ifFalse: [| 0]]]","12345",200),
 ("conditional-reused","let yes := [| 12345]; let no := [| 0]; let flag := true; [| [flag ifTrue: yes ifFalse: no]]","12345",200),
 ("block-call","let f := [:x | x]; let a := 12345; [| [f value: a]]","12345",200),
 ("cell-read","let cell := [Cell with: 12345]; [| [cell value]]","12345",200),
 ("range-size","let range := [0 to: 1079]; [| [range size]]","1080",200),
 ("range-at","let range := [0 to: 1079]; let index := 734; [| [range at: index]]","734",200),
 ("range-zero","[| [[0 to: -1] do: [:i | nil]]; 12345]","12345",30),
 ("range-two","[| [[0 to: 1] do: [:i | nil]]; 12345]","12345",30),
 ("empty-integer-1080","[| [0 to: 1079 do: [:i | nil]]; 12345]","12345",1),
 ("range-one","[| [[0 to: 0] do: [:i | nil]]; 12345]","12345",30),
 ("empty-range-1080","[| [[0 to: 1079] do: [:i | nil]]; 12345]","12345",1),
 ("empty-nested-60x18","[| [[0 to: 17] do: [:y | [[0 to: 59] do: [:x | nil]]]]; 12345]","12345",1),
 ];
 for (label,source,expected,n) in cases {
  if metrics && n==1 {continue;}
  let body=eval(source);let value=id.intern_name(b"value").unwrap();
  let check=|r:Operand|{let r=keep(object(r));let p=keep(object(send(id,r,b"printString",&[])));let b=send(id,p,b"bytes",&[]).as_bytes().unwrap();assert_eq!(borrowed_bytes(b.pointer,b.length).unwrap(),expected.as_bytes(),"{label}");};
  for _ in 0..3 {check(id.send(body,value,&[]).unwrap());}
  collect(id,gc);
  if metrics {
   send(id,gc,b"automaticCollection:",&[Operand::word(0)]);
   let begin=id.intern_name(b"dispatchCountsBegin").unwrap();let end=id.intern_name(b"dispatchCountsEnd").unwrap();
   id.send(id.receiver,begin,&[]).unwrap();let result=id.send(body,value,&[]).unwrap();
   let raw=id.send(id.receiver,end,&[]).unwrap().as_bytes().unwrap();let bytes=borrowed_bytes(raw.pointer,raw.length).unwrap().to_vec();
   let mut counts=BTreeMap::new();
   for line in std::str::from_utf8(&bytes).unwrap().lines(){let (n,hex)=line.split_once('\t').unwrap();let name=String::from_utf8((0..hex.len()).step_by(2).map(|i|u8::from_str_radix(&hex[i..i+2],16).unwrap()).collect()).unwrap();if name!="dispatchCountsEnd" {counts.insert(name,n.parse::<usize>().unwrap());}}
   let raw=send(id,id.receiver,b"dispatchTrace",&[]).as_bytes().unwrap();let trace=String::from_utf8(borrowed_bytes(raw.pointer,raw.length).unwrap().to_vec()).unwrap();
   check(result);send(id,gc,b"automaticCollection:",&[Operand::word(1)]);
   println!("{}",serde_json::json!({"case":label,"sends":counts.values().sum::<usize>(),"selectors":counts,"trace":trace,"source":source}));
  } else {
   let mut times=vec![];
   for _ in 0..3 {collect(id,gc);let t=clock_gettime_nsec_np(16);let mut last=Operand::unit();for _ in 0..n {last=id.send(body,value,&[]).unwrap();std::hint::black_box(last);}let elapsed=clock_gettime_nsec_np(16)-t;check(last);times.push(elapsed as f64/n as f64);}
   collect(id,gc);send(id,gc,b"automaticCollection:",&[Operand::word(0)]);
   let before=send(id,id.receiver,b"allocationCount",&[]).as_word().unwrap();let bytes=send(id,gc,b"allocationBytes",&[]).as_word().unwrap();
   let result=id.send(body,value,&[]).unwrap();
   let objects=send(id,id.receiver,b"allocationCount",&[]).as_word().unwrap()-before;let charged=send(id,gc,b"allocationBytes",&[]).as_word().unwrap()-bytes;
   check(result);send(id,gc,b"automaticCollection:",&[Operand::word(1)]);
   println!("{}",serde_json::json!({"case":label,"cpu_ns_per_invocation":times,"iterations_per_sample":n,"allocated_objects":objects,"charged_bytes":charged,"source":source}));
  }
 }
 // Direct owner calls isolate primitive work from authored callers/control.
 if !metrics {
  let a=eval("12345");let integer=named(b"Integer");let sel=id.intern_name(b"wordOf:").unwrap();let args=[Operand::object(a)];
  let t=clock_gettime_nsec_np(16);for _ in 0..100000 {assert_eq!(id.send(integer,sel,&args).unwrap().as_word(),Some(12345));}let elapsed=clock_gettime_nsec_np(16)-t;
  println!("{}",serde_json::json!({"case":"native-integer-unbox","cpu_ns_per_invocation":elapsed as f64/100000.0}));
 }
}}
